actions.script:
operatorName = '' if (session?.operatorPartyId) { def opPerson = ec.entity.find("mantle.party.Person") .condition("partyId", session.operatorPartyId).one() if (opPerson) operatorName = [(opPerson.firstName ?: ''), (opPerson.lastName ?: '')].findAll{it}.join(' ') }
storeAddr = '' if (rTpl) { storeAddr = [rTpl.addressLine1, rTpl.addressLine2, rTpl.city, rTpl.state, rTpl.pincode].findAll{it}.join(', ') }
storeName = rTpl?.companyName ?: terminal?.terminalName ?: 'Store' storePhone = rTpl?.phone ?: '' storeEmail = rTpl?.email ?: '' taxReg = rTpl?.taxRegistrationNumber ?: terminal?.taxRegistrationNumber ?: '' isRevisedBill = ec.entity.find('zenith.erp.pos.PosTransactionAmendment').condition('transactionId',transactionId).count() > 0 def receiptDesign = isRevisedBill ? 'revised' : (txn.isCredit == 'Y' ? 'credit' : '') def receiptText = { key -> def overrideKey = receiptDesign ? receiptDesign + key.substring(0,1).toUpperCase() + key.substring(1) : key rTpl?.get(overrideKey) ?: rTpl?.get(key) ?: '' } receiptOptions = ec.service.sync().name('zenith.pos.ReceiptTemplateServices.resolve#ReceiptOptions') .parameters([storedJson:rTpl?.receiptOptionsJson,receiptDesign:receiptDesign ?: 'normal']).call().options receiptTones=[:] ['greeting','company','header','information','products','amounts','tax','payments','footer'].each { section -> receiptTones[section]=receiptOptions[section+'Tone']=='darkGrey' ? '#333' : (receiptOptions[section+'Tone']=='lightGrey' ? (section in ['amounts','information','tax'] ? '#333' : '#707070') : '#000') } paperWidth = rTpl?.receiptWidth == '58mm' ? '58mm' : '80mm' showDiscount = rTpl?.showDiscount != 'N' showTaxBreakdown = rTpl?.showTaxBreakdown != 'N' showCustomer = rTpl?.showCustomerInfo != 'N' && receiptOptions.showCustomerRow showPaymentDetails = rTpl?.showPaymentDetails == 'Y' receiptPayments = showPaymentDetails ? ec.entity.find('zenith.erp.pos.PosPayment').condition('transactionId',transactionId).list() : [] headerText = receiptText('headerText') footerText = receiptText('footerText') termsText = receiptText('termsText')
// FOP's bundled base fonts do not contain the rupee glyph. Use a readable currency prefix. cs = 'Rs. ' billNo = txn.transactionNumber ?: txn.transactionId billDate = ec.l10n.format(txn.completedDate ?: txn.entryDate, 'dd/MM/yyyy hh:mm a') customerName = txn.customerName ?: 'Walk-In Customer' customerPhone = txn.customerPhone ?: '' customerGstin = txn.customerTaxRegNumber ?: ''
pdfUnsupported = [receiptOptions.openingPreset!='none' ? receiptOptions.openingMessage : '',storeName,storeAddr,headerText,footerText,termsText, showCustomer && receiptOptions.showCustomerName ? customerName : '',receiptOptions.showCashier ? operatorName : '', receiptOptions.showBillNumber ? receiptOptions.billNumberLabel : '',showCustomer ? receiptOptions.customerLabel : '',receiptOptions.showCashier ? receiptOptions.cashierLabel : '', items.collect { it.productName }].flatten().find { it && it.toString().codePoints().anyMatch { point -> point > 255 } } != null unitLabels = ['OTH_ea':'Nos','WT_g':'g','WT_kg':'kg','VLIQ_ml':'ml','VLIQ_L':'L','LEN_m':'m','LEN_cm':'cm'] totalSaving = (txn.discountTotal ?: 0) as BigDecimal // ZE-POS-005: credit/pay-later marker + amount due, computed in Groovy (no FO FreeMarker arithmetic) isCreditBill = (txn.isCredit == 'Y') creditHasDue = ((txn.payableAmount ?: 0) as BigDecimal) > ((txn.paidAmount ?: 0) as BigDecimal) outstandingAmt = zinr.inr(ec.l10n.format(((txn.payableAmount ?: 0) as BigDecimal) - ((txn.paidAmount ?: 0) as BigDecimal), '#,##0.00'))
